// Typed client of api/openapi.yaml (design.md, decision 3). `paths` is generated by
// `npm run generate`; every path, method and body below is checked against the contract.
import { randomBytes } from "node:crypto";
import createClient from "openapi-fetch";
import type { paths } from "./schema";
import { currentToken } from "../auth/session";

export const API_URL = process.env.DISCOUNT_API_URL ?? "http://localhost:8080";

// `fetch` is resolved per request so a test can stub the global after this module loads.
export const api = createClient<paths>({ baseUrl: API_URL, fetch: (req) => globalThis.fetch(req) });

// W3C Trace Context (spec `telemetry`, "Console calls carry trace context"): every call
// mints a trace id and a parent span id, sends them as `traceparent`, and returns the trace
// id on the outcome so a page can print it next to an error for lookup in Tempo. The
// console exports no spans of its own; the service's spans join the trace we name here.
export type Traceparent = { header: string; traceId: string; parentId: string };

export function newTraceparent(): Traceparent {
  const traceId = randomBytes(16).toString("hex");
  const parentId = randomBytes(8).toString("hex");
  return { header: `00-${traceId}-${parentId}-01`, traceId, parentId };
}

/** The traceparent of the request `call()` is about to issue; consumed by the middleware. */
let pending: Traceparent | null = null;

api.use({
  onRequest({ request }) {
    if (pending) request.headers.set("traceparent", pending.header);
    pending = null;
    // The signed-in operator's bearer, set per request by the middleware (spec: Token on every call).
    const token = currentToken();
    if (token) request.headers.set("authorization", `Bearer ${token}`);
    return request;
  },
});

/** The API answered with a documented error status; `body` is shown verbatim (spec: errors are shown verbatim). */
export type ApiError = { ok: false; unreachable?: undefined; status: number; body: unknown; traceId: string };
/** The service at `API_URL` did not answer at all. */
export type Unreachable = { ok: false; unreachable: true; url: string; traceId: string };
export type Outcome<T> = { ok: true; data: T; status: number; traceId: string } | ApiError | Unreachable;

type Reply<T> = { data?: T; error?: unknown; response: Response };

/** Run one client call under a fresh trace id and fold its three outcomes into `Outcome`. */
export async function call<T>(fn: () => Promise<Reply<T>>): Promise<Outcome<T>> {
  const tp = newTraceparent();
  const traceId = tp.traceId;
  let reply: Reply<T>;
  try {
    // `fn` issues its request synchronously; `onRequest` reads `pending` before any await.
    pending = tp;
    reply = await fn();
  } catch {
    return { ok: false, unreachable: true, url: API_URL, traceId };
  } finally {
    pending = null;
  }
  const status = reply.response.status;
  if (reply.response.ok) return { ok: true, data: reply.data as T, status, traceId };
  return { ok: false, status, body: reply.error ?? null, traceId };
}

/** The URL of the service when any of the outcomes says it is unreachable, else null. */
export function unreachableUrl(...outcomes: Outcome<unknown>[]): string | null {
  for (const o of outcomes) if (!o.ok && o.unreachable) return o.url;
  return null;
}

/** A documented API error among the outcomes, if any. */
export function firstError(...outcomes: Outcome<unknown>[]): ApiError | null {
  for (const o of outcomes) if (!o.ok && !o.unreachable) return o;
  return null;
}

export function dataOr<T>(o: Outcome<T>, fallback: T): T {
  return o.ok ? o.data : fallback;
}
